const $=s=>document.querySelector(s),app=$('#app');
const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const store={get(k,f){try{return JSON.parse(localStorage.getItem('neuro-'+k))??f;}catch{return f;}},set(k,v){try{localStorage.setItem('neuro-'+k,JSON.stringify(v));}catch{}}};
let name=store.get('name',''),buddy=store.get('buddy',0),rating=store.get('rating',1200),tableSize=6,visibility='public',sound=store.get('sound',true),audio,toastTimer;
let room=null,game=null,client=null,view='home',daily=null,botTimer,botKey='',recorded=false,chatOpen=false,playersOpen=false,advancedOpen=false,desktopRulesOpen=false,autoJoin=store.get('autojoin',false),roomList=[],directoryError='',connectionStatus='',generation=0,localReadyAt=null,serverOffset=0,feedback='',submitting=false,typingTimer;
const id=crypto.randomUUID(),ownId=()=>room?.myId||id;
