async function submitAnswer(input){if(game?.phase!=='playing'||submitting)return;const resolution=resolveGuess(question(),input,game.used);if(resolution.suggestions){applyPartySuggestion(resolution);return;}submitting=true;try{let result;if(room.mode==='online')result=(await client.action('answer',{answer:input})).feedback;else result=game.submit(room.mode==='couch'?game.players[game.turn].id:id,input);if(result.ok){feedback='';if($('#answer'))$('#answer').value='';beep(result.answer.points>=85?'rare':'pass');if(room.mode!=='online')renderRoom();}else if(result.suggestions)applyPartySuggestion(result);else throw new Error(result.message);}catch(error){feedback=error.message;if($('#feedback'))$('#feedback').textContent=feedback;}finally{submitting=false;if($('#answer-form button[type="submit"]'))$('#answer-form button[type="submit"]').disabled=game.phase!=='playing'||(room.mode!=='couch'&&game.players[game.turn]?.id!==ownId());}}
function orderedSeats(){const seated=game.players.filter(p=>!p.spectator);const own=seated.findIndex(p=>p.id===ownId());return own>0?[...seated.slice(own),...seated.slice(0,own)]:seated;}
function scheduleBot(){if(room?.mode!=='practice'||game?.phase!=='playing')return;const player=game.players[game.turn],key=`${game.round}:${game.turn}:${game.log.length}`;if(!player?.bot||botKey===key)return;clearTimeout(botTimer);botKey=key;if(Math.random()<.24)return;botTimer=setTimeout(()=>{if(room?.mode!=='practice'||game?.phase!=='playing'||game.players[game.turn]?.id!==player.id)return;const available=question().answers.filter(a=>!game.used.includes(a.name)),common=available.filter(a=>a.points<=60),options=common.length&&Math.random()<.8?common:available;if(options.length){game.submit(player.id,options[Math.floor(Math.random()*options.length)].name);renderRoom();}},2000+Math.random()*4500);}
