 const puffer=root.querySelector('.home-puffer,.scene-puffer');if(!puffer)return;
 if(mode==='door'){puffer.style.left=layout.cx+'px';puffer.style.top=(layout.cy+6)+'px';puffer.style.width=layout.puffer+'px';return;}
 root.style.setProperty('--pf-spr',layout.sprite+'px');root.style.setProperty('--pf-perch',layout.perch+'px');root.toggleAttribute('data-tight',layout.sprite<64);
