 seats.forEach((seat,index)=>{const pos=seatPosition(layout,index,seats.length),which=[1,2,4,5,6,8][index%6],height=layout.perch*perchRatios[which],offset=perchTops[which],y=pos.y-(1-offset)*height*pos.depth;seat.style.left=pos.x+'px';seat.style.top=y+'px';seat.style.zIndex=String(100+Math.round(pos.y));seat.querySelector('.pf-seat-in').style.transform=`scale(${pos.depth})`;seat.querySelector('.pf-perch').style.top=(-offset*height)+'px';seat.querySelector('.pf-plate').style.top=((1-offset)*height+5)+'px';const meter=seat.querySelector('.pf-seat-meter');if(meter)meter.style.top=((1-offset)*height-7)+'px';if(seat.classList.contains('hold'))holder={x:pos.x,y:y-layout.sprite*.5};});
 const origin=root.getBoundingClientRect(),blockers=[...seats].flatMap(seat=>[...seat.querySelectorAll('.pf-spr-wrap,.pf-perch')].filter(el=>getComputedStyle(el).visibility!=='hidden').map(el=>{const b=el.getBoundingClientRect();return {left:b.left-origin.left,right:b.right-origin.left,top:b.top-origin.top,bottom:b.bottom-origin.top};}));
