function modal(title,content,eyebrow='NEURO KRILLION'){if(view==='daily'&&daily){daily.pause();saveDaily();}$('#modal-eyebrow').textContent=eyebrow;$('#modal-content').innerHTML=`<h2>${title}</h2>${content}`;if(!$('#modal').open)$('#modal').showModal();}
function rules(){modal('HOW TO PLAY',`<ol class="rules-list"><li>Answer the question before the puffer explodes on you.</li><li>Rarer answers get you closer to an extra heart.</li><li>No reusing answers for the current question.</li></ol><details class="scoring-details"><summary>SCORING & NEUROSCIENCE</summary><div class="tier-list">${tierRows()}</div><p class="modal-note">Every ${game?.settings.pointsPerHeart||600} points earns a heart, up to ${game?.settings.heartCap||5}. Every new holder gets at least ${game?.settings.minTurn||8} seconds. A pop costs one heart. Last player floating wins.</p><p class="modal-note">Scores are editorial difficulty tiers. Each category has a 100-point answer from an introductory course. Standard abbreviations and unambiguous small typos are accepted. The bank is curated, so it cannot cover every scientifically valid answer.</p></details><button class="big-button" data-action="close-modal">GOT IT</button>`,'PUFFER PARTY');}
