 container.querySelector('.sheet-list').innerHTML=answers.slice(0,state.limit).map(a=>`<div class="bank-entry"><div class="bank-entry-top"><span>${escape(a.name)}</span><span class="tier-badge" style="color:${tierFor(a.points).color}">${tierFor(a.points).name.toUpperCase()} · ${a.points}</span></div><p>${escape(a.explanation)}</p>${a.source?`<a class="answer-source" href="${escape(a.source)}" target="_blank" rel="noopener">Anatomy reference ↗</a>`:''}</div>`).join('')||'<p class="modal-note">No answers match these filters.</p>';
