function bank(){sheetStates=new Map();modal('DEEPER KNOWLEDGE',`<p class="modal-note">${PLAY_BANK.length} broad game prompts, each with ${LIBRARY_STATS.minAnswers.toLocaleString()}–${LIBRARY_STATS.maxAnswers.toLocaleString()} accepted answers. Familiar introductory answers count alongside specialist ones. Every prompt has an introductory-course 100-point gem.</p><input class="bank-search" id="bank-search" aria-label="Search questions and answers" placeholder="Search every topic and answer…"><p class="bank-total">${LIBRARY_STATS.uniqueAnswers.toLocaleString()} distinct answers · ${STUDY_BANK.length} focused study sets</p><div id="bank-list"></div><p class="modal-note">The game uses the broad prompts. Focused study sets help you explore individual topics. Scores are editorial difficulty tiers, not survey frequencies. The library is large but not exhaustive.</p>`,'THE ANSWER BANK');renderBank('');}
